// Generated by muten (native-kit/muten-check.test.jsx): every screen opened in React Native's test environment, and
// every pressable in it pressed. A screen that would crash on a phone, as it opens or as it is used, fails here first.
// The first crash of the native proof of concept (a runtime module reaching for window.addEventListener) was only seen
// on a phone; this is what would have stopped it.
import React from 'react';
import { StyleSheet } from 'react-native';
import { render, fireEvent } from '@testing-library/react-native';
import SCREENS from './muten-screens';
import { POINTS_ONLY, NUMBERS_ONLY, LENGTH_OR_PERCENT } from './muten-style-rules';

// a style value the phone would refuse. Android does not skip it: the screen goes red («String cannot be cast to
// Double») and JavaScript never hears of it, so Metro's log stays clean. Asked here of every element drawn.
const POINTS = new Set(POINTS_ONLY), NUMBERS = new Set(NUMBERS_ONLY), LENGTHS = new Set(LENGTH_OR_PERCENT);
const isNumber = (value) => typeof value === 'number' && Number.isFinite(value);
const isLength = (value) => isNumber(value) || value === 'auto' || (typeof value === 'string' && /^-?\d*\.?\d+%$/.test(value));
function refusedStyles(tree, found = []) {
  if (!tree) return found;
  if (Array.isArray(tree)) { for (const one of tree) refusedStyles(one, found); return found; }
  if (typeof tree !== 'object') return found;
  const style = StyleSheet.flatten(tree.props?.style) || {};
  for (const [key, value] of Object.entries(style)) {
    if (value === undefined || value === null) continue;
    const bad = (POINTS.has(key) && !isNumber(value)) || (NUMBERS.has(key) && !isNumber(value)) || (LENGTHS.has(key) && !isLength(value));
    if (bad) found.push(`<${tree.type}> ${key}: ${JSON.stringify(value)}`);
  }
  refusedStyles(tree.children, found);
  return found;
}

jest.mock('expo-router', () => ({ useLocalSearchParams: () => globalThis.__params || {}, router: { push: jest.fn(), dismissTo: jest.fn() }, usePathname: () => '/', Redirect: () => null, Stack: () => null }));
// the phone's localStorage (SQLite) is a native module: here, one in memory with the same calls
jest.mock('expo-sqlite/localStorage/install', () => { const kept = new Map(); globalThis.localStorage = { getItem: (key) => (kept.has(key) ? kept.get(key) : null), setItem: (key, value) => kept.set(key, String(value)), removeItem: (key) => kept.delete(key), clear: () => kept.clear() }; return {}; }, { virtual: true });
// Reanimated draws CSS animations on the UI thread, which a test does not have (its own mock lacks the CSS API): here
// an animated node is the plain one, so the check still opens the screen, presses everything and reads every style
jest.mock('react-native-reanimated', () => {
  const native = require('react-native');
  const Animated = { View: native.View, Text: native.Text, Image: native.Image, ScrollView: native.ScrollView, createAnimatedComponent: (Component) => Component };
  return { __esModule: true, default: Animated, ...Animated, cubicBezier: () => 'ease', steps: () => 'linear' };
}, { virtual: true });
jest.mock('react-native-safe-area-context', () => require('react-native-safe-area-context/jest/mock').default);
jest.mock('expo-image', () => { const { View } = require('react-native'); return { Image: (props) => <View {...props} /> }; });

for (const [name, params, load, atLeast] of SCREENS) {
  test(`${name}: opens, and every pressable can be pressed`, async () => {
    const errors = [];
    const spy = jest.spyOn(console, 'error').mockImplementation((...args) => { errors.push(args.map(String).join(' ')); });
    globalThis.__params = params;
    const Screen = load();
    const view = await render(<Screen />);
    const refused = refusedStyles(view.toJSON());
    // what a person can press, found as they are announced: buttons, links and checkboxes (muten marks each one)
    const pressables = ['button', 'link', 'checkbox'].flatMap((role) => view.queryAllByRole(role));
    for (const element of pressables) await fireEvent.press(element);
    refused.push(...refusedStyles(view.toJSON()));   // after the presses too: a class turned on brings its own styles
    spy.mockRestore();
    expect(errors).toEqual([]);
    expect([...new Set(refused)]).toEqual([]);   // what Android would refuse, by element and prop
    expect(pressables.length).toBeGreaterThanOrEqual(atLeast);   // fewer: it pressed nothing, so it proved nothing
  });
}
